import { describe, expect, it } from 'vitest'
import { veloraCalldataFeeBps } from './quotes'

// Head of real Augustus v6.2 calldata from api.paraswap.io (Base, 2 000 USDC -> WETH, 2026-10-18).
const ANON =
  ''
const PARTNER =
  ''

describe('Velora calldata fee', () => {
  it('reads the 1 bps anon fee when no partner is passed', () => {
    expect(veloraCalldataFeeBps(ANON)).toBe(1n)
  })
  it('reads no fee with partner=auto-loop', () => {
    expect(veloraCalldataFeeBps(PARTNER)).toBe(0n)
  })
  it('refuses other methods', () => {
    expect(veloraCalldataFeeBps('0x12345678' + PARTNER.slice(10))).toBeNull()
  })
})
